customCSS:
.t, .history { color: #6c7086; }
.join { color: #a6e3a1; }
.part, .quit { color: #6c7086; }
.kick, .error { color: #f38ba8; }
.notice { color: #f9e2af; }
.action { color: #cba6f7; }
.mode, .nick, .topic, .server { color: #94e2d5; }
.highlight { color: #cdd6f4; background-color: #45475a; border-left: 3px solid #cba6f7; padding-left: 8px; }
.reply { color: #6c7086; border-left: 2px solid #89b4fa; padding-left: 6px; }
.oper { color: #1e1e2e; background-color: #f9e2af; }
.reactions { color: #89b4fa; background-color: #313244; }
.card { background-color: #313244; border-color: #6c7086; }
.card-title { color: #89b4fa; }
.card-desc { color: #6c7086; }
.daychange { color: #6c7086; border-color: #313244; }
